# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
from author_batch200_root_greek_leg_a import G,X,H
LG=G+[['希腊 logos','话语、说明、论证、理性等意义']]
DI=G+[['希腊 dia- 与说话词族 → dialogos；dialogikos','交谈；与交谈有关的']]
AP=LG+[['希腊 apologia → 拉丁 apologia','为某个立场或自己所作的辩护'],['英语 apologia','正式的辩护性说明或文章']]
PG=G+[['希腊 pro-“在先” + legein → prolegein；prolegomenon','先说；预先说出的东西'],['英语 prolegomenon；复数 prolegomena','导论、前置讨论']]
WC=[
E('dialectically','/ˌdaɪəˈlektɪkli/','辩证地；通过考察对立关系及其变化','把两种看似相反的力量放在同一个过程里，看它们怎样互相改变。','dialectical + -ly，表达采用辩证思路分析的方式。',G+[['希腊 dialektikos → 拉丁 dialecticus → 英语 dialectical','论辩的；辩证的'],['英语 dialectical → dialectically','辩证的 → 辩证地']],'think dialectically 在哲学或社会理论中，常要求注意关系、张力和变化。具体分析方式取决于理论背景；它不是给普通观点加一个“深刻”的标签，也不是只说两句相反的话。','think dialectically；develop dialectically；interpret something dialectically。','dialectically 多说辩证地；dialectally 说在方言层面。少一个 ic，讨论对象就变了。',('The author examines the two forces dialectically.','作者从相互作用的辩证关系来考察这两种力量。'),('The seminar asks students to think dialectically about change.','研讨课要求学生用辩证思路思考变化。'),sources=['https://www.collinsdictionary.com/dictionary/english/dialectically','https://www.etymonline.com/word/dialectical']),
E('dialogic','英 /ˌdaɪəˈlɒdʒɪk/；美 /ˌdaɪəˈlɑːdʒɪk/','对话的；通过相互回应展开的','一个声音说完，另一个声音真的改变了谈话接下来会怎么走。','接希腊 dialogikos“与对话有关的”；现代也能对应 dialogue + -ic。dia- 不是表示数字二的 di-。',H(DI,'英语 dialogic','具有对话性质的'),'dialogic teaching 重视学生与教师相互回应、追问，而不是只等老师说标准答案。文学中的 dialogic 也可说作品里不同声音相互作用。对话可以有两人，也可以更多，不能从 dia- 猜出“只能两个人”。','dialogic teaching；a dialogic process；dialogic relationships。','dialogic 强调相互回应；monologic 强调单一声音展开。表面上轮流说话，也未必形成深入的 dialogic exchange。',('The teacher used a dialogic approach to the discussion.','教师采用了重视相互回应的讨论方式。'),('The novel creates a dialogic relationship between its narrators.','小说让几位叙述者的声音形成相互回应的关系。'),sources=['https://en.wiktionary.org/wiki/dialogic','https://www.etymonline.com/word/dialogue']),
E('dialogical','英 /ˌdaɪəˈlɒdʒɪkəl/；美 /ˌdaɪəˈlɑːdʒɪkəl/','对话的；以相互回应为基础的','理解不是一个人往外倒出来，而是在来回回应中逐渐形成。','与希腊 dialogikos 相关的 -ical 形容词；英语 dialogical 的记录早于常见的 dialogic 记录，不把它简单画成较晚形容词加 -al。',DI+[['希腊对话词族与英语 -ical 形式 → dialogical','对话性的、相互回应的']],'a dialogical relationship 强调双方都能回应、影响理解，而不只是单方面说服。dialogical 和 dialogic 通常意义接近，领域习惯可能偏爱其中一个；不能用长短机械区分“更深层”或“更正式”。','a dialogical relationship；a dialogical approach；dialogical learning。','dialogical 关注对话关系；dialectical 常关注辩证论证或矛盾关系。它们可以有交集，但并非同义。',('The project encourages dialogical learning.','这个项目鼓励通过相互对话来学习。'),('A dialogical relationship leaves room for disagreement.','一种真正相互回应的关系会为不同意见留下空间。'),sources=['https://www.etymonline.com/word/dialogue','https://www.collinsdictionary.com/dictionary/english/dialogical']),
E('dialogism','/daɪˈælədʒɪzəm/','对话式表达；对话性理论或观念','让不同声音相遇，而不是把整篇文字写成一个声音的独白。','希腊 dialogismos 经晚期拉丁 dialogismos 等形式进入英语，接 dialogos“对话”与 -ismos；现代文学理论又赋予它特定含义。',DI+[['希腊 dialogismos → 晚期拉丁 dialogismos → 英语 dialogism','对话式的表达、论述；后用于对话性研究']],'较旧修辞用法指用人物对话来呈现作者的思想。现代讨论巴赫金等文学理论时，dialogism 关注话语怎样回应其他话语、不同声音怎样共存。它不是简单数一数作品里有几段带引号的台词。','dialogism in fiction；the concept of dialogism；a study of dialogism。','dialogue 可以是一段具体对话；dialogism 通常是在谈一种表达方式或关于对话性的理论。',('The essay examines dialogism in the novel.','文章考察了这部小说中的对话性。'),('The author uses dialogism to present competing views.','作者用对话式表达呈现彼此竞争的观点。'),sources=['https://academic.oup.com/dsh/article/32/suppl_2/ii31/3978683','https://www.merriam-webster.com/dictionary/dialogism','https://en.wiktionary.org/wiki/dialogism']),
E('logos','英 /ˈlɒɡɒs/；美 /ˈloʊɡoʊs/；logo 的复数另读英 /ˈləʊɡəʊz/、美 /ˈloʊɡoʊz/','逻辑论证的说服方式；理性、道等哲学或神学概念；也可能是 logo 的复数','不用“相信我”代替理由，而是把证据和推理摆出来让人判断。','作为概念，直接接希腊 logos“话语、说明、理由、理性”等义；作为标识的复数，则是英语 logo + -s。',H(LG,'英语 logos／特定传统中的 Logos','逻辑说服；理性或道等概念'),'修辞课里的 logos 常指借证据和推理说服。它与 ethos 的可信度、pathos 的情感诉求相对照。某些哲学和基督教语境中大写 Logos 有更专门含义，不能都译成“逻辑”；看见 company logos，则只是在说公司标识的复数。','appeal to logos；logos, ethos and pathos；the concept of Logos。','logos 是名词概念或 logo 的复数形式；logical 是“合乎逻辑的”形容词，不能直接互换。',('The speaker strengthened the argument’s logos with clear evidence.','演讲者用清晰证据加强了论证的逻辑说服力。'),('The course compares uses of Logos in different traditions.','课程比较了不同传统中 Logos 这一概念的用法。'),('The page displays the company logos.','页面展示了这些公司的标识。'),sources=['https://en.wiktionary.org/wiki/logos','https://www.merriam-webster.com/dictionary/logos']),
E('apologia','英 /ˌæpəˈləʊdʒiə/；美 /ˌæpəˈloʊdʒiə/','正式辩护；为某种立场作说明的文章','别人质疑你的立场，你拿出一篇文章解释“我为什么这样想、这样做”。','接希腊 apologia“辩护性发言”，英语也采用其拉丁形式；它与 apology 同源，但保留了辩护这一核心义。',AP,'an apologia for a policy 是为政策辩护的说明，未必承认政策有错。apology 今天最常说道歉，apologia 却通常说自我辩护或立场说明，因此不能看着眼熟就译成“道歉信”。','an apologia for；write an apologia；a personal apologia。','apologia 重点是为立场辩护；apology 的日常核心是表达歉意。有时一篇文章会同时包含两者。',('The book is an apologia for his political choices.','这本书为他的政治选择作辩护。'),('She offered an apologia rather than an admission of error.','她给出的是辩护，而不是认错。'),sources=['https://www.etymonline.com/word/apologia','https://en.wiktionary.org/wiki/apologia']),
E('apologetically','英 /əˌpɒləˈdʒetɪkli/；美 /əˌpɑːləˈdʒetɪkli/','抱歉地；带着歉意地','话还没说完，语气已经在表达“给你添麻烦了”。','apologetic + -ally，接“辩护”词族后来发展出的歉意义。',LG+[['希腊 apologetikos → 晚期拉丁 apologeticus → 英语 apologetic','辩护的；英语后来也说表示歉意的'],['英语 apologetic → apologetically','带着歉意或辩护意味地']],'said apologetically 常见于叙事，描写说话者因迟到、打断、无法帮忙等而显得抱歉。它主要描述语气和态度，不保证已经补救问题。较少见的辩护义要看具体文本。','smile apologetically；say apologetically；shrug apologetically。','apologetically 说表现出歉意；politely 只是有礼貌。礼貌拒绝不一定带有歉意。',('“I’m afraid the shop is closed,” he said apologetically.','“恐怕店已经关门了。”他抱歉地说。'),('She smiled apologetically and moved her bag from the seat.','她歉意地笑了笑，把包从座位上拿开。'),sources=['https://en.wiktionary.org/wiki/apologetically','https://www.merriam-webster.com/dictionary/apologetic']),
E('unapologetically','英 /ˌʌnəpɒləˈdʒetɪkli/；美 /ˌʌnəpɑːləˈdʒetɪkli/','毫无歉意地；坦然、毫不掩饰地','知道别人可能不赞成，仍然明明白白地承认“我就是这样选择的”。','unapologetic + -ally；un- 否定的是表示歉意的态度。',LG+[['英语 apologetic → unapologetic → unapologetically','有歉意的 → 不表示歉意的 → 毫无歉意地']],'unapologetically ambitious 可以是褒义：坦然有抱负，不觉得需要为此道歉。unapologetically rude 则通常是批评：明知无礼仍毫无歉意。评价色彩由它修饰的内容和语境决定。','unapologetically ambitious；unapologetically political；unapologetically rude。','unapologetically 不一定是“理直气壮地做坏事”；它只说不为某种选择或特点表示歉意。',('The film is unapologetically sentimental.','这部电影毫不掩饰自己的感伤风格。'),('He remained unapologetically rude throughout the meeting.','整场会议中他始终态度无礼，且毫无歉意。'),sources=['https://en.wiktionary.org/wiki/unapologetically','https://dictionary.cambridge.org/dictionary/english/unapologetically']),
E('logion','英 /ˈləʊɡiən/；美 /ˈloʊdʒiən/','圣言、宗教领袖的传世语句〔学术〕','把一段被传下来的话单独拎出来，研究它怎样被记录、怎样被理解。','来自希腊 logion，与 logos“话语”相接；希腊语中也有神谕义。',LG+[['希腊 logion → 英语 logion','神谕、传世语句；宗教研究中的语句单位']],'宗教文本研究中 a logion 常指归于某位宗教领袖、尤其耶稣的一则语句，复数 logia。研究者可以讨论它的文本形式、来源和解释；称它为 logion 本身不等于已经证明归属。','a logion attributed to；the interpretation of a logion；the plural logia。','logion 是一则语句；logos 可指话语、理性或特定理论概念。它也不是 logo“标识”的变形。',('The article compares two versions of the logion.','文章比较了这则传世语句的两个版本。'),('The scholar discusses a logion attributed to Jesus.','学者讨论了一则被归于耶稣的语句。'),sources=['https://en.wiktionary.org/wiki/logion','https://www.merriam-webster.com/dictionary/logion']),
E('prolegomenon','英 /ˌprəʊlɪˈɡɒmɪnɒn/；美 /ˌproʊlɪˈɡɑːmənɑːn/','导论；绪论；预备讨论〔正式学术用语〕','进正文之前，先把后面讨论要用的概念和问题讲明白。','希腊 pro-“先” + legein“说”，prolegomenon 是“预先被说出的东西”的名词化形式。',PG,'a prolegomenon to a theory 是通向某套理论的预备讨论，常比一段简单开场白更有内容。它不是日常介绍自己时需要的词；读学术书名、章节名时认识即可。','a prolegomenon to；serve as a prolegomenon；philosophical prolegomenon。','preface 常交代写作背景、目的等；prolegomenon 更常承担理论准备和概念铺垫，但具体作品可能交叉。',('The essay serves as a prolegomenon to the larger study.','这篇文章为后面更大规模的研究作理论铺垫。'),('The prolegomenon defines the book’s central terms.','导论界定了全书的核心术语。'),sources=['https://www.etymonline.com/word/prolegomenon','https://www.merriam-webster.com/dictionary/prolegomenon']),
E('prolegomena','英 /ˌprəʊlɪˈɡɒmɪnə/；美 /ˌproʊlɪˈɡɑːmənə/','导论、绪论；一组预备讨论〔prolegomenon 的复数〕','正式展开之前，要先说的几项基础问题集中放在这里。','保留希腊来源的复数形式：prolegomenon → prolegomena；-a 在此是复数词尾，不是另一个表示内容的词根。',H(PG,'希腊来源的复数形式 prolegomena 也用于英语','多项预备讨论；用作导论标题'),'Prolegomena 常出现在学术书名或章节标题中，可以泛指成组的前置论述。作为普通复数名词时注意复数搭配；如果是一本书的完整标题，句子的数则按书名所指的一部作品处理。','prolegomena to；the following prolegomena；introductory prolegomena。','prolegomena 不是 prolegomenon 后面再加 s；英语保留了这组古典单复数形式。',('These prolegomena establish the terms of the debate.','这些预备论述确定了辩论要使用的概念。'),('The volume opens with prolegomena to the main argument.','这部书以主要论证的预备讨论开篇。'),sources=['https://www.merriam-webster.com/dictionary/prolegomena','https://www.collinsdictionary.com/dictionary/english/prolegomena']),
E('lexicology','英 /ˌleksɪˈkɒlədʒi/；美 /ˌleksɪˈkɑːlədʒi/','词汇学','把词放进一个系统里，研究它们怎样构成、怎样表达意思、怎样互相关联。','英语借自法语 lexicologie；按构词可拆 lexico-“词汇” + -logy“研究”，背后接希腊词语与话语词族。',X+[['法语 lexicologie → 英语 lexicology','词汇 + 研究 → 词汇学']],'lexicology 可以研究词义关系、构词方式、词汇组织及变化。它会问“这些词怎样联系起来”，不只问“这一本词典该怎样编”。当然，词汇研究的结论也能帮助词典编写。','a course in lexicology；historical lexicology；lexicology and semantics。','lexicology 研究词汇系统；lexicography 以词典编纂及其理论为中心。前者不必产出一本词典。',('The course introduces the main questions of lexicology.','课程介绍词汇学的主要问题。'),('Lexicology examines relationships among words.','词汇学考察词与词之间的关系。'),sources=['https://en.wiktionary.org/wiki/lexicology','https://www.merriam-webster.com/dictionary/lexicology']),
]
